import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const root = "/Users/elikafilin/Documents/home_projects/organic-shop-orchestrator/submissions/elika-filin";
const changeSpecs = join(root, "openspec/changes/add-basket/specs");
const mainSpecs = join(root, "openspec/specs");
const DELTA_HEADERS = ["## ADDED Requirements", "## MODIFIED Requirements", "## REMOVED Requirements", "## RENAMED Requirements"];

const trimBlank = (lines) => {
  let s = 0, e = lines.length;
  while (s < e && lines[s].trim() === "") s++;
  while (e > s && lines[e - 1].trim() === "") e--;
  return lines.slice(s, e);
};
const reqName = (l) => l.replace(/^### Requirement:\s*/, "").trim();

function parseDelta(path) {
  const lines = readFileSync(path, "utf8").split("\n");
  const h2 = lines.map((l, i) => ({ l: l.trim(), i })).filter(({ l }) => l.startsWith("## "));
  const ops = h2.filter(({ l }) => DELTA_HEADERS.includes(l));
  const stray = h2.filter(({ l }) => !DELTA_HEADERS.includes(l) && l !== "## Purpose");
  if (stray.length) throw new Error(`${path}: unexpected section(s) ${stray.map((s) => s.l).join(", ")}`);
  if (ops.length !== 1 || ops[0].l !== "## ADDED Requirements") {
    throw new Error(`${path}: this merge handles ADDED-only deltas; found ${ops.map((o) => o.l).join(", ") || "no operations"}`);
  }
  const sectionBody = (idx) => {
    const next = h2.find(({ i }) => i > idx)?.i ?? lines.length;
    return trimBlank(lines.slice(idx + 1, next));
  };
  const purposeIdx = h2.find(({ l }) => l === "## Purpose")?.i;
  const purpose = purposeIdx === undefined ? null : sectionBody(purposeIdx);
  const added = sectionBody(ops[0].i);
  const names = added.filter((l) => l.startsWith("### Requirement:")).map(reqName);
  if (names.length === 0) throw new Error(`${path}: ADDED section has no requirements`);
  return { purpose, added, names };
}

for (const cap of ["basket-api", "basket-web", "catalog-web"]) {
  const delta = parseDelta(join(changeSpecs, cap, "spec.md"));
  const mainPath = join(mainSpecs, cap, "spec.md");
  if (!existsSync(mainPath)) {
    if (!delta.purpose?.length) throw new Error(`${cap}: new capability without a usable ## Purpose`);
    if (delta.purpose.join(" ").length < 50) console.warn(`warning: ${cap}: Purpose is shorter than 50 characters`);
    const out = [`# ${cap} Specification`, "", "## Purpose", "", ...delta.purpose, "", "## Requirements", "", ...delta.added, ""].join("\n");
    mkdirSync(dirname(mainPath), { recursive: true });
    writeFileSync(mainPath, out);
    console.log(`created ${cap}/spec.md with ${delta.names.length} requirement(s): ${delta.names.join(" | ")}`);
    continue;
  }
  const main = readFileSync(mainPath, "utf8");
  const mainLines = main.split("\n");
  const h2 = mainLines.map((l) => l.trim()).filter((l) => l.startsWith("## "));
  if (h2[h2.length - 1] !== "## Requirements") throw new Error(`${cap}: last section of the main spec is not ## Requirements`);
  const existing = mainLines.filter((l) => l.startsWith("### Requirement:")).map(reqName);
  const dup = delta.names.filter((n) => existing.includes(n));
  if (dup.length) throw new Error(`${cap}: requirement(s) already present, needs a merge rather than an append: ${dup.join(" | ")}`);
  if (delta.purpose) console.log(`note: ${cap}: delta carries a ## Purpose; the existing main-spec Purpose is kept`);
  writeFileSync(mainPath, `${main.replace(/\s+$/, "")}\n\n${delta.added.join("\n")}\n`);
  console.log(`updated ${cap}/spec.md: appended ${delta.names.length} requirement(s): ${delta.names.join(" | ")}`);
}
EOF
