import { join } from "node:path";
const root = process.cwd();
const DELTA = ["## ADDED Requirements","## MODIFIED Requirements","## REMOVED Requirements","## RENAMED Requirements"];
let problems = 0;
const bad = (m) => { problems++; console.log("PROBLEM: " + m); };
for (const cap of ["basket-api","basket-web","catalog-web"]) {
  const main = readFileSync(join(root,"openspec/specs",cap,"spec.md"),"utf8");
  const delta = readFileSync(join(root,"openspec/changes/add-basket/specs",cap,"spec.md"),"utf8");
  const ml = main.split("\n"), dl = delta.split("\n");
  if (ml[0] !== `# ${cap} Specification`) bad(`${cap}: title is ${JSON.stringify(ml[0])}`);
  const h2 = ml.map(l=>l.trim()).filter(l=>l.startsWith("## "));
  if (JSON.stringify(h2) !== JSON.stringify(["## Purpose","## Requirements"])) bad(`${cap}: h2 sections are ${h2.join(", ")}`);
  for (const d of DELTA) if (main.includes(d)) bad(`${cap}: delta header left: ${d}`);
  if (/TBD/.test(main.split("## Requirements")[0])) bad(`${cap}: TBD purpose`);
  const names = (ls, p) => ls.filter(l=>l.startsWith(p)).map(l=>l.slice(p.length).trim());
  const dReq = names(dl,"### Requirement:"), mReq = names(ml,"### Requirement:");
  const dSc = names(dl,"#### Scenario:"), mSc = names(ml,"#### Scenario:");
  for (const r of dReq) if (!mReq.includes(r)) bad(`${cap}: missing requirement ${r}`);
  for (const s of dSc) if (!mSc.includes(s)) bad(`${cap}: missing scenario ${s}`);
  // every ADDED requirement block text present verbatim
  const addedBody = delta.split("## ADDED Requirements")[1].trim();
  if (!main.includes(addedBody)) bad(`${cap}: ADDED body not present verbatim in main`);
  // purpose check for new specs
  if (delta.includes("## Purpose")) {
    const dp = delta.split("## Purpose")[1].split("## ADDED Requirements")[0].trim();
    const mp = main.split("## Purpose")[1].split("## Requirements")[0].trim();
    if (dp !== mp) bad(`${cap}: purpose differs from delta`);
  }
  const reqUnderReqs = ml.indexOf("## Requirements") < ml.findIndex(l=>l.startsWith("### Requirement:"));
  if (!reqUnderReqs) bad(`${cap}: a requirement precedes ## Requirements`);
  console.log(`${cap}: title ok · sections ${h2.join(",")} · requirements ${mReq.length} (delta ${dReq.length}) · scenarios ${mSc.length} (delta ${dSc.length}) · purpose chars ${main.split("## Purpose")[1].split("## Requirements")[0].trim().length}`);
}
